// Image: the same names as Buffer A, with other values, other fields and another body
float camRot = 1.4;
struct Hit
{
	float dist;
	float depth;
};
Hit mk(float x) { return Hit(x, 2.0); }
float df(vec3 p) { return length(p) - 2.0; }
#define SCALE df(vec3(1.0))

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
	Hit h = mk(fragCoord.x);
	vec4 b = texture(iChannel0, fragCoord / iResolution.xy);
	fragColor = vec4(h.depth * camRot, SCALE, df(vec3(fragCoord, 0.)) + b.x, 1.0);
}

// Buffer A: a global, a struct, a function and a macro that the Image pass also has, but differently
float camRot = 1.5;
struct Hit
{
	float dist;
	float id;
};
Hit mk(float x) { return Hit(x, 1.0); }
float df(vec3 p) { return length(p) - 1.0; }
#define SCALE df(vec3(1.0))

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
	Hit h = mk(fragCoord.x);
	fragColor = vec4(h.dist * camRot, SCALE, df(vec3(fragCoord, 0.)), 1.0);
}
